Proceso ClasificacionNota
    Definir nota Como Entero;
    Leer nota;
    Si nota >= 9 Entonces
        Escribir 4;
    SiNo
        Si nota >= 7 Entonces
            Escribir 3;
        SiNo
            Si nota >= 5 Entonces
                Escribir 2;
            SiNo
                Escribir 1;
            FinSi
        FinSi
    FinSi
FinProceso
